// Fast analytic projection of the same articulated scene for devices without WebGL.
import * as THREE from './vendor/three.module.js';
export class SoftwareRenderer {
 constructor({canvas}){this.canvas=canvas;this.ctx=canvas.getContext('2d');if(!this.ctx)throw Error('No canvas context');this.shadowMap={};this.isSoftware=true;this.dpr=1;this.w=1;this.h=1;}
 setPixelRatio(dpr){this.dpr=1;}
 setClearColor(){}
 setSize(w,h){this.w=w;this.h=h;this.canvas.width=Math.round(w*this.dpr);this.canvas.height=Math.round(h*this.dpr);this.ctx.setTransform(this.dpr,0,0,this.dpr,0,0);}
 render(scene,camera){scene.updateMatrixWorld();camera.updateMatrixWorld();camera.matrixWorldInverse.copy(camera.matrixWorld).invert();const view=new THREE.Matrix4().multiplyMatrices(camera.projectionMatrix,camera.matrixWorldInverse),ctx=this.ctx,w=this.w,h=this.h,draws=[];ctx.clearRect(0,0,w,h);
 const project=(v,m)=>new THREE.Vector3(...v).applyMatrix4(m).applyMatrix4(view).multiply(new THREE.Vector3(w/2,-h/2,1)).add(new THREE.Vector3(w/2,h/2,0));
 const color=(c,f)=>{const rgb=c.clone().multiplyScalar(f).convertLinearToSRGB();return `rgb(${Math.min(255,Math.round(rgb.r*255))},${Math.min(255,Math.round(rgb.g*255))},${Math.min(255,Math.round(rgb.b*255))})`;};
 scene.traverseVisible(mesh=>{if(!mesh.isMesh)return;const material=Array.isArray(mesh.material)?mesh.material[0]:mesh.material;if(!material?.color||(material.transparent&&material.opacity<.6))return;const geometry=mesh.geometry;geometry.computeBoundingBox();const box=geometry.boundingBox,center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3()).multiplyScalar(.5),position=project(center.toArray(),mesh.matrixWorld);const worldCenter=center.clone().applyMatrix4(mesh.matrixWorld);const c=material.color;
 if(geometry.type==='TubeGeometry'){const points=geometry.parameters.path.getPoints(20).map(p=>project(p.toArray(),mesh.matrixWorld));draws.push({z:worldCenter.z,paint:()=>{ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.strokeStyle=color(c,1);ctx.lineWidth=Math.max(1.2,geometry.parameters.radius*h/(camera.top-camera.bottom)*2);ctx.lineCap='round';ctx.stroke();}});return;}
 const axes=[[size.x,0,0],[0,size.y,0],[0,0,size.z]].map(axis=>project(center.clone().add(new THREE.Vector3(...axis)).toArray(),mesh.matrixWorld).sub(position));const a=axes.reduce((n,v)=>n+v.x*v.x,0),d=axes.reduce((n,v)=>n+v.y*v.y,0),b=axes.reduce((n,v)=>n+v.x*v.y,0),dist=Math.hypot(a-d,2*b),rx=Math.sqrt(Math.max(.01,(a+d+dist)/2)),ry=Math.sqrt(Math.max(.01,(a+d-dist)/2)),angle=.5*Math.atan2(2*b,a-d);
 draws.push({z:worldCenter.z,paint:()=>{ctx.save();ctx.translate(position.x,position.y);ctx.rotate(angle);ctx.beginPath();ctx.ellipse(0,0,rx,ry,0,0,Math.PI*2);if(geometry.type==='TorusGeometry'){ctx.strokeStyle=color(c,.8);ctx.lineWidth=3;ctx.stroke();}else{const gradient=ctx.createRadialGradient(-rx*.28,-ry*.32,0,rx*.15,ry*.18,Math.max(rx,ry)*1.35);gradient.addColorStop(0,color(c,1.1));gradient.addColorStop(.55,color(c,.97));gradient.addColorStop(1,color(c,.64));if(mesh.userData.faceHead){const vertical=Math.sqrt(d),sx=Math.sin(angle)*vertical,sy=Math.cos(angle)*vertical,beardGradient=ctx.createLinearGradient(-sx,-sy,sx,sy);beardGradient.addColorStop(0,color(c,1.08));beardGradient.addColorStop(.55,color(c,1));beardGradient.addColorStop(.57,'#a29d94');beardGradient.addColorStop(1,'#7f7b73');ctx.fillStyle=beardGradient;}else ctx.fillStyle=gradient;ctx.fill();}ctx.restore();}});});
 draws.sort((a,b)=>a.z-b.z);for(const item of draws)item.paint();
 const image=ctx.getImageData(0,0,this.canvas.width,this.canvas.height),pixels=image.data,bayer=[0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5],width=this.canvas.width;
 for(let i=0;i<pixels.length;i+=4){if(!pixels[i+3])continue;const n=i/4,x=n%width,y=Math.floor(n/width),l=(pixels[i]*.2126+pixels[i+1]*.7152+pixels[i+2]*.0722)/255,v=l>(bayer[(y%4)*4+x%4]+.5)/16?251:11;pixels[i]=pixels[i+1]=pixels[i+2]=v;}ctx.putImageData(image,0,0);
 }
}
